# Vulnerability 1, Python Backend Server Side RCE
## Clarification
Chroma has two server-side implementations: one in Python and the other in Rust. By default you will get a Rust Server, and this vulnerability only affect the Python Backend
## Detail
First, the API Server of Chroma has an interface called create_collection.
And it will calls the load_create_collection_configuration_from_json function.
https://github.com/chroma-core/chroma/blob/main/chromadb/server/fastapi/__init__.py#L816
```
@trace_method("FastAPI.create_collection", OpenTelemetryGranularity.OPERATION)
    async def create_collection(
        self,
        request: Request,
        tenant: str,
        database_name: str,
    ) -> CollectionModel:
        def process_create_collection(
            request: Request, tenant: str, database: str, raw_body: bytes
        ) -> CollectionModel:
            create = validate_model(CreateCollection, orjson.loads(raw_body))
            if not create.configuration:
                if create.metadata:
                    configuration = (
                        create_collection_configuration_from_legacy_collection_metadata(
                            create.metadata
                        )
                    )
                else:
                    configuration = None
            else:
                configuration = load_create_collection_configuration_from_json(
                    create.configuration
                )
```
And in load_create_collection_configuration_from_json function, it will use the known_embedding_functions, and call build_from_config.
https://github.com/chroma-core/chroma/blob/main/chromadb/api/collection_configuration.py#L317
```
def load_create_collection_configuration_from_json(
    json_map: Dict[str, Any]
) -> CreateCollectionConfiguration:
    if json_map.get("hnsw") is not None and json_map.get("spann") is not None:
        raise ValueError("hnsw and spann cannot both be provided")

    result = CreateCollectionConfiguration()

    # Handle vector index configuration
    if json_map.get("hnsw") is not None:
        result["hnsw"] = json_to_create_hnsw_configuration(json_map["hnsw"])

    if json_map.get("spann") is not None:
        result["spann"] = json_to_create_spann_configuration(json_map["spann"])

    # Handle embedding function configuration
    if json_map.get("embedding_function") is not None:
        ef_config = json_map["embedding_function"]
        if ef_config["type"] == "legacy":
            warnings.warn(
                "legacy embedding function config",
                DeprecationWarning,
                stacklevel=2,
            )
        else:
            ef = known_embedding_functions[ef_config["name"]]
            result["embedding_function"] = ef.build_from_config(ef_config["config"])

    return result
```
https://github.com/chroma-core/chroma/blob/main/chromadb/utils/embedding_functions/sentence_transformer_embedding_function.py#L87
But in sentence_transformer_embedding_function, it didn't liimit the model, and we can also set the trust_remote_code parameter throught the kwargs.
```
def build_from_config(config: Dict[str, Any]) -> "EmbeddingFunction[Documents]":
        model_name = config.get("model_name")
        device = config.get("device")
        normalize_embeddings = config.get("normalize_embeddings")
        kwargs = config.get("kwargs", {})

        if model_name is None or device is None or normalize_embeddings is None:
            assert False, "This code should not be reached"

        return SentenceTransformerEmbeddingFunction(
            model_name=model_name,
            device=device,
            normalize_embeddings=normalize_embeddings,
            **kwargs,
        )
```
Therefore, an attacker can easily send a request to make the server load a remote malicious embedding model, thereby achieving RCE.


#  Vulnerability 2, Python Client SDK RCE
## Detail
In the following function, you can see that Chroma has a logic where: if the user explicitly specifies an _embedding_function during usage, the system will prioritize using the user-specified one; if not specified, it will query the _embedding_function stored in the server-side configuration. As a result, an attacker can poison the Collection in advance, and once the attacker uses it normally, RCE (Remote Code Execution) will occur.  This behavior is not dependent on whether the server-side implementation is Python-based or Rust-based.
https://github.com/chroma-core/chroma/blob/0706035a226c0b357cc0c442120d2c2211ddb037/chromadb/api/models/CollectionCommon.py#L755
```
 def _embed(self, input: Any, is_query: bool = False) -> Embeddings:
        if self._embedding_function is not None and not isinstance(
            self._embedding_function, DefaultEmbeddingFunction
        ):
            if is_query:
                return self._embedding_function.embed_query(input=input)
            else:
                return self._embedding_function(input=input)

        config_ef = self.configuration.get("embedding_function")
        if config_ef is not None:
            if is_query:
                return config_ef.embed_query(input=input)
            else:
                return config_ef(input=input)
        schema = self.schema
        schema_embedding_function: Optional[EmbeddingFunction[Embeddable]] = None
        if schema is not None:
            override = schema.keys.get(EMBEDDING_KEY)
            if (
                override is not None
                and override.float_list is not None
                and override.float_list.vector_index is not None
                and override.float_list.vector_index.config.embedding_function
                is not None
            ):
                schema_embedding_function = cast(
                    EmbeddingFunction[Embeddable],
                    override.float_list.vector_index.config.embedding_function,
                )
            elif (
                schema.defaults.float_list is not None
                and schema.defaults.float_list.vector_index is not None
                and schema.defaults.float_list.vector_index.config.embedding_function
                is not None
            ):
                schema_embedding_function = cast(
                    EmbeddingFunction[Embeddable],
                    schema.defaults.float_list.vector_index.config.embedding_function,
                )

        if schema_embedding_function is not None:
            if is_query and hasattr(schema_embedding_function, "embed_query"):
                return schema_embedding_function.embed_query(input=input)
            return schema_embedding_function(input=input)
        if self._embedding_function is None:
            raise ValueError(
                "You must provide an embedding function to compute embeddings."
                "https://docs.trychroma.com/guides/embeddings"
            )
        if is_query:
            return self._embedding_function.embed_query(input=input)
        else:
            return self._embedding_function(input=input)
```
## Client Demo
```
import chromadb


def victim(collection_name: str):

    client = chromadb.HttpClient(host="chroma_ip", port=8000)


    collection = client.get_collection(name=collection_name)

    collection.add(ids=["1"], documents=["test"])

    return collection_name
victim("shared_data_389d58")
```
